function validate([words]) {
  if (words.length < 1 || words.length > 100000) return 'words needs 1 to 10^5 entries.';
  if (words.some(word => !/^[a-z]{2}$/.test(word))) return 'Each word is exactly two lowercase letters.';
  return null;
}

