function longestPalindrome(words) {
  const count = new Map();
  for (const word of words) {
    count.set(word, (count.get(word) ?? 0) + 1);
  }

  let length = 0;
  let hasCenter = false;
  for (const [word, times] of count) {
    const mirror = word[1] + word[0];
    if (word === mirror) {
      length += Math.floor(times / 2) * 4;
      if (times % 2 === 1) hasCenter = true;
    } else if (word < mirror && count.has(mirror)) {
      length += Math.min(times, count.get(mirror)) * 4;
    }
  }

  if (hasCenter) length += 2;
  return length;
}

