function longestPalindrome(words) {
  // Try every set of disjoint pairs (i, j) where words[j] is words[i] reversed; such pairs wrap around the middle.
  // A leftover entry that reads the same both ways may then sit in the very middle.
  const used = new Array(words.length).fill(false);
  const middle = () => words.some((word, k) => !used[k] && word[0] === word[1]) ? 2 : 0;
  const search = from => {
    let best = middle();
    for (let i = from; i < words.length; i++) {
      if (used[i]) continue;
      for (let j = i + 1; j < words.length; j++) {
        if (used[j] || words[j] !== words[i][1] + words[i][0]) continue;
        used[i] = used[j] = true;
        best = Math.max(best, 4 + search(i + 1));
        used[i] = used[j] = false;
      }
    }
    return best;
  };
  return search(0);
}

