function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 7);
  const letters = 'abcdefghijklmnopqrstuvwxyz'.slice(0, size === 'large' ? 3 + Math.floor(rand() * 24) : 2 + Math.floor(rand() * 2));
  const pick = () => letters[Math.floor(rand() * letters.length)];
  const words = [];
  for (let i = 0; i < n; i++) words.push(pick() + pick());
  return [words];
}
